Method.Implementation:
	$$$TRACE("Inside Select PRVDR_ID Method")
	set npi=pRequest.StringValue
    $$$TRACE("NPI: "_npi)
	set pResponse = ##class(Ens.StringResponse).%New()
	// So this get all the records
	set pRes = ##class(EnsLib.SQL.Snapshot).%New()
	set pRes.MaxRowsToGet = -1
	set tSQL = "SELECT PRVDR_ID FROM CORPPRV.ADV_PROVIDER WHERE NTNL_PRVDR_ID =?" 
	set ioParms=1
	set ioParms(1)=npi
	set ioParms(1,"SqlType")=3

 	set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL,.ioParms)

	if tSC = 1
	{
		$$$TRACE("Successfully executed Query:"_tSQL)
		If ($ISOBJECT(pRes)&&(pRes.RowCount>0)){
			$$$TRACE("Retrieve provider id from the Response")
			set rowNum=pRes.Next(.sc)
			$$$TRACE("Error Status"_sc)
			if ($$$ISERR(sc)){
				$$$TRACE("Error Reading result set")
				set tSC=$$$ERROR("Error Reading Result set")
			}else{
				set prvdrId=pRes.Get("PRVDR_ID")
				$$$TRACE("rowNum "_rowNum_" PRVDR_ID: "_prvdrId)
				set pResponse.StringValue = prvdrId
			}
		}
	}
	else
	{
		$$$TRACE("Failed to execute Query:"_tSQL)	
	}

	Quit tSC
